#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/text/localizable/localizable_property.hpp"

#include <chrono>
#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// SearchField's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/search_field.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// The query: a view onto the inner editor's text (see TextBox). A change raises text_changed and, after search_delay, search_requested.
template <typename Declaring>
struct SearchFieldTextCapability {
    PropertyView<std::string, SearchFieldTextCapability<Declaring>> text;

    static void assign(SearchFieldTextCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.text), std::move(incoming));
    }

    static std::string read(const SearchFieldTextCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::string current = control.read_view(capability.text);
        return current;
    }
};

// The hint the empty field shows, such as "Search": a view onto the inner editor's placeholder (see TextBox).
template <typename Declaring>
struct SearchFieldPlaceholderTextCapability {
    PropertyView<std::string, SearchFieldPlaceholderTextCapability<Declaring>> placeholder_text;

    static void assign(SearchFieldPlaceholderTextCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.placeholder_text), std::move(incoming));
    }

    static std::string read(const SearchFieldPlaceholderTextCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::string current = control.read_view(capability.placeholder_text);
        return current;
    }
};

// How long typing must pause before search_requested is raised, 300 ms by default; zero raises it at each change. Negative or over 10 s throws std::invalid_argument. A change applies to the next edit.
template <typename Declaring>
struct SearchFieldSearchDelayCapability {
    PropertyCell<std::chrono::milliseconds, SearchFieldSearchDelayCapability<Declaring>> search_delay{std::chrono::milliseconds(300)};

    static void assign(SearchFieldSearchDelayCapability& capability, std::chrono::milliseconds incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.search_delay), incoming);
        if (!capability.search_delay.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.search_delay));
    }
};

// Whether a search is running; the field shows an activity strip along its bottom and is busy to assistive technology. The application sets and clears it.
template <typename Declaring>
struct SearchFieldBusyCapability {
    PropertyCell<bool, SearchFieldBusyCapability<Declaring>> busy{};

    static void assign(SearchFieldBusyCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.busy), incoming);
        if (!capability.busy.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.busy));
    }
};

// Every SearchField capability, in the order the declaring class takes them.
template <typename Declaring>
struct SearchFieldCapabilities : public SearchFieldTextCapability<Declaring>,
                                 public SearchFieldPlaceholderTextCapability<Declaring>,
                                 public SearchFieldSearchDelayCapability<Declaring>,
                                 public SearchFieldBusyCapability<Declaring> {};

} // namespace gui_forms
